    // Nama kegiatan di catatan aktivitas
    'Masuk aplikasi' => ["Signed in to the app", "登录应用", "アプリにログイン", "تسجيل الدخول إلى التطبيق", "Connexion à l'application", "Anmeldung in der App", "Inicio de sesión en la aplicación"],
