    'Membuka kunci login' => ["Unlocked a sign-in", "解除登录锁定", "ログインロックを解除", "فتح قفل تسجيل الدخول", "Déblocage d'une connexion", "Anmeldesperre aufgehoben", "Inicio de sesión desbloqueado"],
    'Mengganti password' => ["Changed password", "修改密码", "パスワードを変更", "تغيير كلمة المرور", "Changement de mot de passe", "Passwort geändert", "Cambio de contraseña"],
