    'Admin mengganti password' => ["Admin changed password", "管理员修改密码", "管理者がパスワードを変更", "مشرف غيّر كلمة المرور", "Changement de mot de passe administrateur", "Admin hat Passwort geändert", "El administrador cambió la contraseña"],
    'Menyimpan akun admin' => ["Saved an admin account", "保存管理员账户", "管理者アカウントを保存", "حفظ حساب مشرف", "Enregistrement d'un compte administrateur", "Admin-Konto gespeichert", "Cuenta de administrador guardada"],
    'Mengaktifkan akun admin' => ["Activated an admin account", "启用管理员账户", "管理者アカウントを有効化", "تفعيل حساب مشرف", "Activation d'un compte administrateur", "Admin-Konto aktiviert", "Cuenta de administrador activada"],
    'Menonaktifkan akun admin' => ["Deactivated an admin account", "停用管理员账户", "管理者アカウントを無効化", "تعطيل حساب مشرف", "Désactivation d'un compte administrateur", "Admin-Konto deaktiviert", "Cuenta de administrador desactivada"],
