    'Mengunduh cadangan' => ["Downloaded a backup", "下载备份", "バックアップをダウンロード", "تنزيل نسخة احتياطية", "Téléchargement d'une sauvegarde", "Sicherung heruntergeladen", "Descarga de copia de seguridad"],

